const G36_ICONS={"aurora36": "data:image/webp;base64,", "comet36": "data:image/webp;base64,", "halo36": "data:image/webp;base64,", "judgement36": "data:image/webp;base64,", "lance36": "data:image/webp;base64,", "nova36": "data:image/webp;base64,", "orbit36": "data:image/webp;base64,", "seraph36": "data:image/webp;base64,", "void36": "data:image/webp;base64,"};setTimeout(()=>{try{const st=document.createElement("style");st.textContent=Object.entries(G36_ICONS).map(([k,v])=>`.gear25-art.g44-${k}{background-image:url(${v})!important;background-size:82% auto!important;background-position:center!important;background-repeat:no-repeat!important}`).join("");document.head.appendChild(st);const oa=Progress.art;Progress.art=function(i){const h=oa.apply(this,arguments);return i&&G36_ICONS[i.variant]&&!h.includes("g44-"+i.variant)?h.replace('class="gear25-art','class="gear25-art g44-ic g44-'+i.variant):h;};}catch(e){}},0);